PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT DISTINCT ?party ?partyLabel ?count WHERE {
  {
    SELECT ?party ( COUNT( DISTINCT ?position ) AS ?count ) WHERE {
      ?person p:P39 ?position .
      ?position ps:P39 / wdt:P279 * wd:Q15964890 .
      ?position pq:P4100 ?party .
    }
    GROUP BY ?party
  }
  OPTIONAL {
    ?party rdfs:label ?partyLabel .
    FILTER ( LANG( ?partyLabel ) = "en" )
  }
}
ORDER BY DESC ( ?count )

