      ?mid1 wdt:P279 ?mid2 .
      ?mid2 wdt:P279 ?common .
      BIND(3 AS ?dist1)
    } UNION {
      wd:Q35657 wdt:P279 ?mid1 .
      ?mid1 wdt:P279 ?mid2 .
      ?mid2 wdt:P279 ?mid3 .
      ?mid3 wdt:P279 ?common .
      BIND(4 AS ?dist1)
    }
  }
  {
    {
      wd:Q1093829 wdt:P279 ?common .
      BIND(1 AS ?dist2)
    } UNION {
      wd:Q1093829 wdt:P279 ?mid1 .
      ?mid1 wdt:P279 ?common .
      BIND(2 AS ?dist2)
    } UNION {
      wd:Q1093829 wdt:P279 ?mid1 .
      ?mid1 wdt:P279 ?mid2 .
      ?mid2 wdt:P279 ?common .
      BIND(3 AS ?dist2)
    } UNION {
      wd:Q1093829 wdt:P279 ?mid1 .
      ?mid1 wdt:P279 ?mid2 .
      ?mid2 wdt:P279 ?mid3 .
      ?mid3 wdt:P279 ?common .
