PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT DISTINCT 
  ?item 
  ?itemLabel 
  ?image 
  (GROUP_CONCAT(DISTINCT ?instrumentLabel; SEPARATOR = "; ") AS ?instruments) 
  ?birth 
  ?birthLabel 
  ?website 
  ?musicbrainz 
  ?songkick 
  ?twitter 
  ?facebook 
  ?wikipedia
WHERE {
  ?item (rdfs:label | skos:altLabel | wdt:P1449) "Corey Hart" @en .

  {
    ?item (wdt:P31/wdt:P279*) wd:Q215380 .  # musical group
  } UNION {
    ?item (wdt:P106/wdt:P279*) wd:Q639669 .  # musician
  } UNION {
    ?item (wdt:P31/wdt:P279*) wd:Q2088357 .  # musical ensemble
  }

  OPTIONAL { ?item wdt:P18 ?image . }
  OPTIONAL { ?item wdt:P19 ?birth . }
  OPTIONAL { ?item wdt:P1303 ?instrument . }
  OPTIONAL { ?item wdt:P856 ?website . }
  OPTIONAL { ?item wdt:P434 ?musicbrainz . }
  OPTIONAL { ?item wdt:P3478 ?songkick . }
  OPTIONAL { ?item wdt:P2002 ?twitter . }
  OPTIONAL { ?item wdt:P2013 ?facebook . }

  # Get labels
  OPTIONAL { ?item rdfs:label ?itemLabel . FILTER(LANG(?itemLabel) = "en") }
  OPTIONAL { ?birth rdfs:label ?birthLabel . FILTER(LANG(?birthLabel) = "en") }
  OPTIONAL { ?instrument rdfs:label ?instrumentLabel . FILTER(LANG(?instrumentLabel) = "en") }

  # Wikipedia page
  ?wikipedia schema:about ?item ;
             schema:inLanguage "en" ;
             schema:isPartOf <https://en.wikipedia.org/> .

}
GROUP BY ?item ?itemLabel ?image ?birth ?birthLabel ?website ?musicbrainz ?songkick ?twitter ?facebook ?wikipedia

