    wd:P57 rdfs:label ?propertyLabel .
    FILTER(LANG(?propertyLabel) = "en")
    OPTIONAL { ?value rdfs:label ?valueLabel . FILTER(LANG(?valueLabel) = "en") }
    BIND(COALESCE(?valueLabel, ?value) AS ?valueDisplay)
  }
  UNION
  {
    wd:Q4901654 p:P364 ?stmt .
    ?stmt ps:P364 ?value .
    wd:P364 rdfs:label ?propertyLabel .
    FILTER(LANG(?propertyLabel) = "en")
    OPTIONAL { ?value rdfs:label ?valueLabel . FILTER(LANG(?valueLabel) = "en") }
    BIND(COALESCE(?valueLabel, ?value) AS ?valueDisplay)
  }
  UNION
  {
    wd:Q4901654 p:P495 ?stmt .
    ?stmt ps:P495 ?value .
    wd:P495 rdfs:label ?propertyLabel .
    FILTER(LANG(?propertyLabel) = "en")
    OPTIONAL { ?value rdfs:label ?valueLabel . FILTER(LANG(?valueLabel) = "en") }
    BIND(COALESCE(?valueLabel, ?value) AS ?valueDisplay)
  }
  UNION
  {
    wd:Q4901654 p:P345 ?stmt .
    ?stmt ps:P345 ?value .
    wd:P345 rdfs:label ?propertyLabel .
    FILTER(LANG(?propertyLabel) = "en")
    BIND(?value AS ?valueDisplay)
  }
  UNION
  {
    wd:Q4901654 p:P577 ?stmt .
    ?stmt ps:P577 ?value .
    wd:P577 rdfs:label ?propertyLabel .
    FILTER(LANG(?propertyLabel) = "en")
    BIND(?value AS ?valueDisplay)
  }
  UNION
  {
    wd:Q4901654 schema:description ?valueDisplay .
    FILTER(LANG(?valueDisplay) = "en")
