    ?item p:P625 / psv:P625 ?coord .
    ?coord wikibase:geoLatitude ?latitude ; wikibase:geoLongitude ?longitude .
  }
  OPTIONAL {
    ?item p:P2046 / psv:P2046 ?areaStmt .
    ?areaStmt wikibase:quantityAmount ?area ; wikibase:quantityUnit ?areaUnit .
    OPTIONAL {
      ?areaUnit rdfs:label ?areaUnitLabel .
      FILTER(LANG(?areaUnitLabel) = "en")
    }
  }
  OPTIONAL {
    ?item p:P2043 / psv:P2043 ?lengthStmt .
    ?lengthStmt wikibase:quantityAmount ?length ; wikibase:quantityUnit ?lengthUnit .
    OPTIONAL {
      ?lengthUnit rdfs:label ?lengthUnitLabel .
      FILTER(LANG(?lengthUnitLabel) = "en")
    }
  }
  OPTIONAL {
