    ?widthStmt wikibase:quantityAmount ?width ; wikibase:quantityUnit ?widthUnit .
    OPTIONAL {
      ?widthUnit rdfs:label ?widthUnitLabel .
      FILTER(LANG(?widthUnitLabel) = "en")
    }
  }
  OPTIONAL {
    ?item p:P2547 / psv:P2547 ?perimeterStmt .
    ?perimeterStmt wikibase:quantityAmount ?perimeter ; wikibase:quantityUnit ?perimeterUnit .
    OPTIONAL {
