    }
  }
  OPTIONAL {
    ?item p:P2044 / psv:P2044 ?elevationStmt .
    ?elevationStmt wikibase:quantityAmount ?elevation ; wikibase:quantityUnit ?elevationUnit .
    OPTIONAL {
      ?elevationUnit rdfs:label ?elevationUnitLabel .
      FILTER(LANG(?elevationUnitLabel) = "en")
    }
  }
  OPTIONAL {
    ?item wdt:P361 ?partOf .
    OPTIONAL {
      ?partOf rdfs:label ?partOfLabel .
      FILTER(LANG(?partOfLabel) = "en")
    }
  }
  OPTIONAL {
    ?item wdt:P131 ?locatedIn .
    OPTIONAL {
      ?locatedIn rdfs:label ?locatedInLabel .
      FILTER(LANG(?locatedInLabel) = "en")
    }
  }
