PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?class((?dist1 + ?dist2) AS ?totalDistance) WHERE {
  OPTIONAL {
    wd:Q262 wdt:P31 ?class .
    BIND(1 AS ?dist1)
  }
  OPTIONAL {
    wd:Q262 wdt:P31 ?p1 .
    ?p1 wdt:P279 ?class .
    BIND(2 AS ?dist1)
  }
  OPTIONAL {
    wd:Q262 wdt:P31 ?p1 .
    ?p1 wdt:P279 ?p2 .
    ?p2 wdt:P279 ?class .
    BIND(3 AS ?dist1)
  }
  OPTIONAL {
    wd:Q800 wdt:P31 ?class .
    BIND(1 AS ?dist2)
  }
  OPTIONAL {
    wd:Q800 wdt:P31 ?p1 .
    ?p1 wdt:P279 ?class .
    BIND(2 AS ?dist2)
  }
  OPTIONAL {
    wd:Q800 wdt:P31 ?p1 .
    ?p1 wdt:P279 ?p2 .
    ?p2 wdt:P279 ?class .
    BIND(3 AS ?dist2)
  }
  FILTER(BOUND(?dist1) && BOUND(?dist2))
}
ORDER BY ASC(?totalDistance)
LIMIT 1

