PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT DISTINCT ?actor ?actorLabel ?role ?roleLabel ?earlierFilm ?earlierFilmLabel ?laterFilm ?laterFilmLabel ( YEAR( ?laterDate ) - YEAR( ?earlierDate ) AS ?diffYears ) WHERE {
  BIND( wd:Q81328 AS ?actor ) .
  ?earlierFilm ( wdt:P31 / wdt:P279 * ) wd:Q11424 ; wdt:P577 ?earlierDate ; p:P161 [ ps:P161 ?actor ; pq:P453 ?role ] .
  ?laterFilm ( wdt:P31 / wdt:P279 * ) wd:Q11424 ; wdt:P577 ?laterDate ; p:P161 [ ps:P161 ?actor ; pq:P453 ?role ] .
  FILTER ( ?laterDate > ?earlierDate ) FILTER ( NOT EXISTS {
    ?otherFilm ( wdt:P31 / wdt:P279 * ) wd:Q11424 ; wdt:P577 ?otherDate ; p:P161 [ ps:P161 ?actor ; pq:P453 ?role ] .
    FILTER ( ?otherDate > ?laterDate )
  }
  ) OPTIONAL {
    ?actor rdfs:label ?actorLabel .
    FILTER ( LANG( ?actorLabel ) = "en" )
  }
  OPTIONAL {
    ?role rdfs:label ?roleLabel .
    FILTER ( LANG( ?roleLabel ) = "en" )
  }
  OPTIONAL {
    ?earlierFilm rdfs:label ?earlierFilmLabel .
    FILTER ( LANG( ?earlierFilmLabel ) = "en" )
  }
  OPTIONAL {
    ?laterFilm rdfs:label ?laterFilmLabel .
    FILTER ( LANG( ?laterFilmLabel ) = "en" )
  }
}
ORDER BY DESC ( ?diffYears )

