PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pr: <http://www.wikidata.org/prop/reference/>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?country ?countryLabel ?inceptionYear ?dissolutionYear (GROUP_CONCAT(DISTINCT ?referenceUrl; SEPARATOR="|") AS ?references)
WHERE {
  BIND(wd:Q153665 AS ?country)
  ?country rdfs:label ?countryLabel .
  FILTER(LANG(?countryLabel) = "en")
  OPTIONAL { ?country wdt:P571 ?inception . }
  OPTIONAL { ?country wdt:P580 ?inception . }
  BIND(IF(BOUND(?inception), YEAR(?inception), "") AS ?inceptionYear)
  OPTIONAL { ?country wdt:P576 ?dissolution . }
  OPTIONAL { ?country wdt:P582 ?dissolution . }
  BIND(IF(BOUND(?dissolution), YEAR(?dissolution), "") AS ?dissolutionYear)
  OPTIONAL {
    ?country p:P571|p:P580|p:P576|p:P582 ?statement .
    ?statement prov:wasDerivedFrom / (pr:P248 | pr:P854) ?referenceUrl .
  }
}
GROUP BY ?country ?countryLabel ?inceptionYear ?dissolutionYear
ORDER BY ASC(?inceptionYear)
LIMIT 10

