SELECT DISTINCT ?commonEntity WHERE { wd:Q34006 ?p1 ?commonEntity . wd:Q607505 ?p2 ?commonEntity . FILTER(?commonEntity != wikibase:Item) }

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT DISTINCT ?location WHERE { wd:Q3360468 (wdt:P30 | wdt:P17 | wdt:P131)+ ?location .}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
SELECT DISTINCT ?label WHERE {
  wd:Q184554 rdfs:label ?label .
  FILTER ( LANGMATCHES( LANG( ?label ) , "en" ) )
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
ASK WHERE { wd:Q47074422 (wdt:P31 / wdt:P279*) wd:Q80686 . }

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?type WHERE {
  wd:Q146190 wdt:P31 ?type .
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?coordinates WHERE {
  wd:Q4191 wdt:P625 ?coordinates .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?personLabel ?birthDate ?deathDate WHERE {
  wd:Q8254555 rdfs:label ?personLabel .
  OPTIONAL {
    wd:Q8254555 wdt:P569 ?birthDate .
  }
  OPTIONAL {
    wd:Q8254555 wdt:P570 ?deathDate .
  }
  FILTER ( LANG( ?personLabel ) = "en" )
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
ASK WHERE {
  wd:Q34086 wdt:P40 ?child
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT DISTINCT ?city ?cityLabel ?country ?countryLabel WHERE {
  ?city ( wdt:P31 / wdt:P279 * ) wd:Q515 ; wdt:P17 ?country ; rdfs:label ?cityLabel .
  FILTER ( LANG( ?cityLabel ) = "en" && CONTAINS( STR( ?cityLabel ) , "Tromsø" ) ) FILTER ( NOT EXISTS {
    ?country wdt:P31 wd:Q3024240
  }
  ) ?country rdfs:label ?countryLabel .
  FILTER ( LANG( ?countryLabel ) = "en" )
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?personLabel ?birthDate ?deathDate WHERE {
  BIND(wd:Q6128975 AS ?person)
  ?person wdt:P31 wd:Q5 .
  ?person rdfs:label ?personLabel .
  FILTER(LANG(?personLabel) = "en")
  OPTIONAL {
    ?person wdt:P569 ?birthDate .
  }
  OPTIONAL {
    ?person wdt:P570 ?deathDate .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
SELECT ?label WHERE { wd:Q127367 rdfs:label ?label . FILTER (LANG(?label) = "fr") }

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?personLabel ?birthDate ?deathDate WHERE {
  BIND( wd:Q287817 AS ?person ) .
  ?person rdfs:label ?personLabel .
  FILTER ( LANG( ?personLabel ) = "en" ) .
  OPTIONAL {
    ?person wdt:P569 ?birthDate .
  }
  OPTIONAL {
    ?person wdt:P570 ?deathDate .
  }
}
